from datetime import datetime, timedelta

current_day = get_current_day()
current_year = current_day.split("-")[0]

emails = search_emails(query="family reunion", sender=None)

if not emails:
    raise ValueError("No emails found regarding the family reunion.")

bodies = [email.body for email in emails]
combined_body = "\n".join(bodies)

lines = combined_body.splitlines()
date_str = None
time_str = None
location_str = None

for line in lines:
    line_lower = line.lower()
    if "date:" in line_lower:
        idx = line_lower.find("date:")
        date_str = line[idx+5:].strip()
    elif "time:" in line_lower:
        idx = line_lower.find("time:")
        time_str = line[idx+5:].strip()
    elif "location:" in line_lower:
        idx = line_lower.find("location:")
        location_str = line[idx+9:].strip()
    elif "place:" in line_lower:
        idx = line_lower.find("place:")
        location_str = line[idx+6:].strip()

if not date_str or not time_str or not location_str:
    raise ValueError("Could not extract date, time, or location from the emails.")

# Parse date
try:
    event_date = datetime.strptime(date_str, "%Y-%m-%d").date()
except ValueError:
    try:
        event_date = datetime.strptime(date_str, "%B %d, %Y").date()
    except ValueError:
        try:
            event_date = datetime.strptime(date_str, "%B %d").date()
            event_date = event_date.replace(year=int(current_year))
        except ValueError:
            raise ValueError(f"Could not parse date: {date_str}")

# Parse time
try:
    start_time = datetime.strptime(time_str, "%H:%M").time()
except ValueError:
    try:
        start_time = datetime.strptime(time_str, "%I:%M %p").time()
    except ValueError:
        try:
            start_time = datetime.strptime(time_str, "%H:%M %p").time()
        except ValueError:
            raise ValueError(f"Could not parse time: {time_str}")

# Calculate end time
start_dt = datetime.combine(event_date, start_time)
end_dt = start_dt + timedelta(hours=4)

# Create event details
event_details = {
    "title": "Family Reunion",
    "description": "Family reunion event.",
    "start_time": start_dt.isoformat(),
    "end_time": end_dt.isoformat(),
    "location": location_str,
    "participants": list(set([email.sender for email in emails]))
}

# Send email with event attachment
attachment = {
    "type": "event",
    "event_details": event_details
}

send_email(
    recipients=list(set([email.sender for email in emails])),
    subject="Family Reunion Event",
    body="Please find the details of the family reunion below.",
    attachments=[attachment],
    cc=None,
    bcc=None
)
